import React, { useState, useEffect } from 'react';
import './BuildingForm.css';

const BuildingForm = ({ 
  onSave, 
  onCancel, 
  isVisible = false 
}) => {
  const [formData, setFormData] = useState({
    nombre: '',
    descripcion: '',
    activo: true
  });
  
  const [currentStep, setCurrentStep] = useState(1); // 1: Formulario, 2: Seleccionar ubicación
  const [isCapturingCoords, setIsCapturingCoords] = useState(false);
  const [capturedCoords, setCapturedCoords] = useState(null);

  // Resetear form cuando se abre/cierra
  useEffect(() => {
    if (isVisible) {
      setFormData({ nombre: '', descripcion: '', activo: true });
      setCurrentStep(1);
      setCapturedCoords(null);
      setIsCapturingCoords(false);
    }
  }, [isVisible]);

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleNextStep = () => {
    if (!formData.nombre.trim()) {
      alert('El nombre del edificio es requerido');
      return;
    }
    setCurrentStep(2);
    startCoordinateCapture();
  };

  const handleBackStep = () => {
    setCurrentStep(1);
    setIsCapturingCoords(false);
  };

  const startCoordinateCapture = () => {
    setIsCapturingCoords(true);
    if (window.startCoordinateCapture) {
      window.startCoordinateCapture((coords) => {
        setCapturedCoords(coords);
        setIsCapturingCoords(false);
      });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!formData.nombre.trim()) {
      alert('El nombre del edificio es requerido');
      return;
    }
    
    if (!capturedCoords) {
      alert('Debes seleccionar la ubicación del edificio en el mapa');
      return;
    }

    const buildingData = {
      nombre: formData.nombre.trim(),
      descripcion: formData.descripcion.trim(),
      activo: formData.activo,
      ubicacion: {
        type: 'Point',
        coordinates: [capturedCoords.lng, capturedCoords.lat]
      },
      poligono: {
        type: 'Point',
        coordinates: [capturedCoords.lng, capturedCoords.lat]
      }
    };

    try {
      await onSave(buildingData);
      onCancel(); // Cerrar el formulario después de guardar
    } catch (error) {
      console.error('Error al guardar:', error);
      alert('Error al guardar el edificio: ' + error.message);
    }
  };

  if (!isVisible) return null;

  return (
    <div className="building-form-overlay">
      <div className="building-form-container">
        <div className="form-header">
          <h3>🏗️ Agregar Nuevo Edificio</h3>
          <div className="step-indicator">
            Paso {currentStep} de 2
          </div>
        </div>
        
        <form onSubmit={handleSubmit}>
          {/* PASO 1: Datos del edificio */}
          {currentStep === 1 && (
            <div className="form-step">
              <div className="form-group">
                <label htmlFor="nombre">Nombre del Edificio *</label>
                <input
                  type="text"
                  id="nombre"
                  name="nombre"
                  value={formData.nombre}
                  onChange={handleInputChange}
                  placeholder="Ej: Edificio de Ingeniería"
                  required
                />
              </div>

              <div className="form-group">
                <label htmlFor="descripcion">Descripción</label>
                <textarea
                  id="descripcion"
                  name="descripcion"
                  value={formData.descripcion}
                  onChange={handleInputChange}
                  placeholder="Descripción del edificio..."
                  rows="3"
                />
              </div>

              <div className="form-group checkbox-group">
                <label>
                  <input
                    type="checkbox"
                    name="activo"
                    checked={formData.activo}
                    onChange={handleInputChange}
                  />
                  Edificio activo
                </label>
              </div>

              <div className="form-actions">
                <button type="button" onClick={onCancel} className="cancel-btn">
                  Cancelar
                </button>
                <button 
                  type="button" 
                  onClick={handleNextStep}
                  className="next-btn"
                  disabled={!formData.nombre.trim()}
                >
                  Siguiente → Seleccionar Ubicación
                </button>
              </div>
            </div>
          )}

          {/* PASO 2: Seleccionar ubicación */}
          {currentStep === 2 && (
            <div className="form-step">
              <div className="form-group">
                <label>Ubicación del Edificio *</label>
                <div className="coordinate-section">
                  {!capturedCoords ? (
                    <div className="capture-instructions">
                      <p>🖱️ <strong>Haz click en el mapa</strong> para seleccionar la ubicación del edificio</p>
                      <div className="capture-status">
                        {isCapturingCoords ? (
                          <div className="capturing-active">
                            ⏳ Esperando que selecciones un punto en el mapa...
                          </div>
                        ) : (
                          <button 
                            type="button" 
                            className="capture-btn"
                            onClick={startCoordinateCapture}
                          >
                            📍 Activar Selección en Mapa
                          </button>
                        )}
                      </div>
                    </div>
                  ) : (
                    <div className="coordinates-display">
                      <p>✅ <strong>Ubicación seleccionada:</strong></p>
                      <div className="coordinate-details">
                        <p><strong>Latitud:</strong> {capturedCoords.lat.toFixed(6)}</p>
                        <p><strong>Longitud:</strong> {capturedCoords.lng.toFixed(6)}</p>
                      </div>
                      <button 
                        type="button" 
                        className="change-coords-btn"
                        onClick={startCoordinateCapture}
                      >
                        🔄 Cambiar Ubicación
                      </button>
                    </div>
                  )}
                </div>
              </div>

              <div className="form-actions">
                <button type="button" onClick={handleBackStep} className="back-btn">
                  ← Volver a Datos
                </button>
                <button 
                  type="submit" 
                  className="save-btn"
                  disabled={!capturedCoords}
                >
                  💾 Guardar Edificio
                </button>
              </div>
            </div>
          )}
        </form>
      </div>

      {/* Overlay de captura activa */}
      {isCapturingCoords && (
        <div className="capture-overlay-active">
          <div className="capture-message">
            <h3>🎯 Selecciona la ubicación</h3>
            <p>Haz <strong>CLICK en cualquier parte del mapa</strong> para establecer la ubicación del edificio</p>
            <button 
              type="button" 
              onClick={() => setIsCapturingCoords(false)}
              className="cancel-capture-btn"
            >
              Cancelar Selección
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default BuildingForm;
